import os
import json
from typing import Any, Dict, List, Optional

import boto3


def _get_text(item: Dict[str, Any], *keys: str) -> Optional[str]:
    for key in keys:
        value = item.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
        if isinstance(value, dict):
            for nested_key in ("Text", "Value", "value", "content"):
                nested_value = value.get(nested_key)
                if isinstance(nested_value, str) and nested_value.strip():
                    return nested_value.strip()
    return None


def _get_float(item: Dict[str, Any], *keys: str) -> Optional[float]:
    for key in keys:
        value = item.get(key)
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, str):
            try:
                return float(value.replace(",", "").strip())
            except ValueError:
                pass
        if isinstance(value, dict):
            for nested_key in ("Value", "value", "Amount", "amount", "Text", "text"):
                nested_value = value.get(nested_key)
                if isinstance(nested_value, (int, float)):
                    return float(nested_value)
                if isinstance(nested_value, str):
                    try:
                        return float(nested_value.replace(",", "").strip())
                    except ValueError:
                        pass
    return None


def _normalize_expense_items(expense_item: Dict[str, Any]) -> List[Dict[str, Any]]:
    items = []
    line_item_groups = expense_item.get("LineItemGroups", []) or expense_item.get("LineItemGroups", [])
    for group in line_item_groups:
        for line_item in group.get("LineItems", []) or []:
            fields = {}
            for field in line_item.get("LineItemExpenseFields", []) or []:
                ft = field.get("Type", {}).get("Text") or field.get("Type", {}).get("Confidence", "")
                val = field.get("ValueDetection", {}).get("Text")
                if ft:
                    fields[ft.lower()] = val
            items.append(
                {
                    "description": fields.get("description") or fields.get("item") or fields.get("product"),
                    "quantity": _get_float(fields, "quantity"),
                    "unit_price": _get_float(fields, "unitprice", "unit_price", "price"),
                    "amount": _get_float(fields, "amount", "total"),
                    "category": fields.get("category"),
                }
            )
    return items


def normalize_expense_fields(document_bytes: bytes, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Normalize extracted expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.

    Standard schema:
    {
      "vendor_name": str|null,
      "invoice_number": str|null,
      "invoice_date": str|null,
      "currency": str|null,
      "subtotal": float|null,
      "tax": float|null,
      "tip": float|null,
      "total": float|null,
      "payment_method": str|null,
      "address": str|null,
      "line_items": [
        {"description": str|null, "quantity": float|null, "unit_price": float|null, "amount": float|null, "category": str|null}
      ],
      "raw_provider_response": dict
    }
    """
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_DEFAULT_REGION"))
    response = client.analyze_expense(Document={"Bytes": document_bytes})

    normalized: Dict[str, Any] = {
        "vendor_name": None,
        "invoice_number": None,
        "invoice_date": None,
        "currency": None,
        "subtotal": None,
        "tax": None,
        "tip": None,
        "total": None,
        "payment_method": None,
        "address": None,
        "line_items": [],
        "raw_provider_response": response,
    }

    expense_docs = response.get("ExpenseDocuments", []) or []
    if not expense_docs:
        return normalized

    doc = expense_docs[0]
    for summary_field in doc.get("SummaryFields", []) or []:
        field_type = (summary_field.get("Type", {}) or {}).get("Text", "")
        value = (summary_field.get("ValueDetection", {}) or {}).get("Text")
        if not field_type:
            continue

        key = field_type.lower().replace(" ", "_")
        if key in ("vendor_name", "supplier_name", "merchant_name", "recipient"):
            normalized["vendor_name"] = value or normalized["vendor_name"]
        elif key in ("invoice_receipt_id", "invoice_number", "document_number", "receipt_id"):
            normalized["invoice_number"] = value or normalized["invoice_number"]
        elif key in ("invoice_receipt_date", "invoice_date", "date"):
            normalized["invoice_date"] = value or normalized["invoice_date"]
        elif key in ("currency",):
            normalized["currency"] = value or normalized["currency"]
        elif key in ("subtotal", "amount_before_tax"):
            normalized["subtotal"] = _get_float(summary_field, "ValueDetection")
        elif key in ("tax", "tax_amount"):
            normalized["tax"] = _get_float(summary_field, "ValueDetection")
        elif key in ("tip", "gratuity"):
            normalized["tip"] = _get_float(summary_field, "ValueDetection")
        elif key in ("total", "amount_due", "amount_paid", "grand_total"):
            normalized["total"] = _get_float(summary_field, "ValueDetection")
        elif key in ("payment_method", "payment_type"):
            normalized["payment_method"] = value or normalized["payment_method"]
        elif key in ("address", "vendor_address", "billing_address"):
            normalized["address"] = value or normalized["address"]

    line_items = _normalize_expense_items(doc)
    if line_items:
        normalized["line_items"] = line_items

    return normalized


def normalize_expense_fields_json(document_bytes: bytes, region_name: Optional[str] = None) -> str:
    return json.dumps(normalize_expense_fields(document_bytes, region_name=region_name), ensure_ascii=False)
